declare(strict_types=1);

function render_operator_page(): void
{
    $user=current_user();
    $canHandleOrders=user_has_capability('orders_floor',$user);
    $canHandleAccounts=user_has_capability('cashier_accounts',$user);
    $canSuperviseShift=user_has_capability('shift_supervision',$user);
    $accommodationLiveEnabled=accommodation_live_operations_enabled();
    $accommodationCanPost=$accommodationLiveEnabled && $canHandleAccounts;
    $accommodationCanManage=is_admin() || $canSuperviseShift;
    $startupOpenTable=max(0,(int)($_GET['open_table']??0));
    $startupTableIntent=$startupOpenTable>0 && ($canHandleOrders||$canHandleAccounts);
    $firstTab=$startupTableIntent?'tables':(($canHandleOrders||$canHandleAccounts)?'attention':'items');
    panel_header('کار روزانه','operator',$startupTableIntent?['operator-startup-table-detail']:[]);
